import path from 'node:path';
import type { ScanReport } from '../types.ts';

function sanitizeWorkerName(dirName: string): string {
  const base = path.basename(dirName).toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '');
  return base ? `${base}-edge` : 'edge-anything-worker';
}

export function generateWranglerConfig(scan: ScanReport, outDir: string): string {
  const hasKind = (kind: string): boolean => scan.bindings.some((b) => b.kind === kind);
  const workerName = sanitizeWorkerName(outDir);

  const lines: string[] = [
    '// Generated by edge-anything — edit binding IDs before `wrangler deploy`',
    '{',
    '  "$schema": "node_modules/wrangler/config-schema.json",',
    `  "name": ${JSON.stringify(workerName)},`,
    '  "main": "src/index.ts",',
    '  "compatibility_date": "2026-11-01",',
  ];

  if (scan.requiresNodejsCompat) {
    lines.push('  "compatibility_flags": ["nodejs_compat"],');
  }

  const blocks: string[] = [];

  if (hasKind('d1')) {
    blocks.push(
      [
        '  "d1_databases": [',
        '    {',
        '      "binding": "DB",',
        `      "database_name": ${JSON.stringify(`${workerName}-db`)},`,
        '      "database_id": "00000000-0000-0000-0000-000000000000",',
        '      "migrations_dir": "migrations"',
        '    }',
        '  ]',
      ].join('\n'),
    );
  }

  if (hasKind('hyperdrive')) {
    blocks.push(
      [
        '  "hyperdrive": [',
        '    {',
        '      "binding": "HYPERDRIVE",',
        '      "id": "00000000000000000000000000000000"',
        '    }',
        '  ]',
      ].join('\n'),
    );
  }

  if (hasKind('kv')) {
    blocks.push(
      [
        '  "kv_namespaces": [',
        '    {',
        '      "binding": "CACHE",',
        '      "id": "00000000000000000000000000000000"',
        '    }',
        '  ]',
      ].join('\n'),
    );
  }

  if (hasKind('r2')) {
    blocks.push(
      [
        '  "r2_buckets": [',
        '    {',
        '      "binding": "BUCKET",',
        `      "bucket_name": ${JSON.stringify(`${workerName}-bucket`)}`,
        '    }',
        '  ]',
      ].join('\n'),
    );
  }

  if (hasKind('queues')) {
    blocks.push(
      [
        '  "queues": {',
        '    "producers": [',
        '      {',
        '        "binding": "JOBS",',
        `        "queue": ${JSON.stringify(`${workerName}-jobs`)}`,
        '      }',
        '    ]',
        '  }',
      ].join('\n'),
    );
  }

  if (hasKind('durable_objects')) {
    blocks.push(
      [
        '  "durable_objects": {',
        '    "bindings": [',
        '      {',
        '        "name": "STATE_DO",',
        '        "class_name": "EdgeStateDO"',
        '      }',
        '    ]',
        '  }',
      ].join('\n'),
    );
  }

  if (hasKind('cron')) {
    blocks.push(
      [
        '  "triggers": {',
        '    "crons": ["*/15 * * * *"]',
        '  }',
      ].join('\n'),
    );
  }

  if (hasKind('workers_ai')) {
    blocks.push(
      [
        '  "ai": {',
        '    "binding": "AI"',
        '  }',
      ].join('\n'),
    );
  }

  blocks.push(
    [
      '  "observability": {',
      '    "enabled": true',
      '  }',
    ].join('\n'),
  );

  lines.push(blocks.join(',\n'));
  lines.push('}');
  return `${lines.join('\n')}\n`;
}
